insert into public.quiz_quizzes (id, label, title, subtitle, mode, position, time_limit) values
  ('debutant', 'Quiz débutant', 'Les bases de l’électricité et des centrales', 'Unités, équipements, sources d’énergie et sécurité électrique.', 'examen', 1, 120),
  ('intermediaire', 'Quiz intermédiaire', 'Exploiter une centrale à cycle combiné', 'Turbine à gaz, chaudière de récupération, alternateur et ISO 50001.', 'examen', 2, 120),
  ('expert', 'Quiz expert', 'Performance, calculs et protections', 'Rendements, émissions, lois de similitude et protections de l’alternateur.', 'examen', 3, 120)
insert into public.quiz_questions (id, quiz_id, position, level, prompt, choices, answer, explanation, calc) values
  ('debutant-01', 'debutant', 1, null, 'Quelle est l’unité utilisée pour mesurer la puissance d’un appareil électrique ?', '["Le volt (V)","L’ampère (A)","Le watt (W)","Le kilowattheure (kWh)"]'::jsonb, 'C', 'Le watt mesure la puissance, c’est-à-dire la quantité d’énergie utilisée ou fournie à un instant donné. Une ampoule LED peut, par exemple, avoir une puissance de 10 W.', false),
  ('debutant-02', 'debutant', 2, null, 'Quel équipement convertit principalement l’énergie solaire en électricité ?', '["Un transformateur","Un panneau photovoltaïque","Un groupe électrogène","Une batterie"]'::jsonb, 'B', 'Un panneau photovoltaïque transforme directement la lumière du soleil en énergie électrique.', false),
  ('debutant-03', 'debutant', 3, null, 'Que signifie l’unité « kWh » présente sur une facture d’électricité ?', '["Kilowatt heureux","Kilowattheure","Kilowatt haute tension","Kilowatt hydraulique"]'::jsonb, 'B', 'Le kilowattheure est une unité d’énergie. Un appareil de 1 000 W, soit 1 kW, utilisé pendant une heure consomme 1 kWh.', false),
  ('debutant-04', 'debutant', 4, null, 'Quel appareil protège une installation en coupant le courant lorsqu’une anomalie est détectée ?', '["Une prise électrique","Une multiprise","Un disjoncteur","Une ampoule"]'::jsonb, 'C', 'Le disjoncteur coupe automatiquement le circuit en cas de surcharge ou de court-circuit. Les dispositifs différentiels complètent la protection des personnes contre certains défauts d’isolement.', false),
  ('debutant-05', 'debutant', 5, null, 'Quelle énergie une centrale hydroélectrique utilise-t-elle principalement ?', '["Le vent","L’eau","Le gaz","Le soleil"]'::jsonb, 'B', 'Une centrale hydroélectrique utilise le mouvement ou la chute de l’eau pour entraîner une turbine reliée à un alternateur.', false),
  ('debutant-06', 'debutant', 6, null, 'Dans une centrale thermique, quel équipement transforme généralement l’énergie mécanique de rotation en énergie électrique ?', '["Le disjoncteur","Le panneau solaire","Le compteur électrique","L’alternateur"]'::jsonb, 'D', 'La turbine entraîne un alternateur, qui transforme l’énergie mécanique de rotation en énergie électrique.', false),
  ('debutant-07', 'debutant', 7, null, 'Quelle est la conséquence principale de l’encrassement des filtres du caisson d’aspiration d’une turbine à gaz ?', '["Une hausse de la puissance par réduction de la température d’entrée","Aucune conséquence tant que le filtre n’est pas colmaté","Une baisse de la température d’échappement uniquement","Une perte de charge accrue qui réduit le débit d’air, donc la puissance, et dégrade le rendement"]'::jsonb, 'D', 'Une perte de charge à l’aspiration diminue la pression d’entrée du compresseur, donc le débit massique et le taux de compression. La puissance baisse et le heat rate se dégrade. Le suivi de la perte de charge (ΔP) est le bon indicateur pour une maintenance prédictive.', false),
  ('debutant-08', 'debutant', 8, null, 'Quelle énergie produit une centrale de 250 MW fonctionnant à pleine puissance pendant 6 heures ?', '["42 MWh","256 MWh","1 500 MWh","15 000 MWh"]'::jsonb, 'C', 'Énergie = puissance × durée = 250 MW × 6 h = 1 500 MWh.', true),
  ('debutant-09', 'debutant', 9, null, 'Quel est le constituant principal du gaz naturel ?', '["Le propane","L’hydrogène","Le butane","Le méthane"]'::jsonb, 'D', 'Le gaz naturel est composé à plus de 80 à 95 % de méthane (CH₄), avec de l’éthane, du propane, de l’azote et du CO₂ en quantités variables.', false),
  ('debutant-10', 'debutant', 10, null, 'Quelle séquence correspond à la logique d’une consignation électrique ?', '["Vérifier l’absence de tension, puis séparer, puis condamner","Séparer, condamner, identifier puis vérifier l’absence de tension, mettre à la terre et en court-circuit","Condamner, puis commencer le travail, puis séparer","Mettre à la terre, puis séparer, puis vérifier l’absence de tension"]'::jsonb, 'B', 'On sépare l’installation de toute source, on condamne la séparation (cadenas, étiquette), on identifie l’ouvrage, puis on vérifie l’absence de tension (VAT) avant de mettre à la terre et en court-circuit. La VAT n’a de sens qu’une fois la séparation faite, et la mise à la terre vient après la VAT.', false),
  ('intermediaire-01', 'intermediaire', 1, null, 'Quand la température ambiante augmente, que devient la puissance maximale d’une turbine à gaz ?', '["Elle augmente, car l’air est plus chaud et plus énergétique","Elle diminue, car l’air est moins dense et le débit massique chute","Elle reste constante grâce à la régulation","Elle augmente uniquement à charge partielle"]'::jsonb, 'B', 'Un air plus chaud est moins dense : le débit massique aspiré par le compresseur baisse, tout comme le taux de compression effectif. La puissance chute typiquement de 0,5 à 0,9 % par °C. C’est la raison d’être des systèmes de refroidissement de l’air d’admission (fogging, évaporatif).', false),
  ('intermediaire-02', 'intermediaire', 2, null, 'Quel concept est propre à la norme ISO 50001 par rapport à une norme de management générique comme l’ISO 9001 ?', '["La revue de direction","L’amélioration continue (PDCA)","La situation de référence énergétique et les indicateurs de performance énergétique (IPE)","L’audit interne"]'::jsonb, 'C', 'L’ISO 50001 impose d’établir une situation de référence énergétique (SRE) et des IPE normalisés par les variables pertinentes (charge, météo, production) pour démontrer l’amélioration de la performance énergétique. Les autres éléments sont communs à toutes les normes de système de management.', false),
  ('intermediaire-03', 'intermediaire', 3, null, 'Un alternateur de 100 MVA fonctionne à cos φ = 0,8 et à sa puissance apparente nominale. Quelle puissance active délivre-t-il ?', '["60 MW","80 MW","100 MW","125 MW"]'::jsonb, 'B', 'P = S × cos φ = 100 × 0,8 = 80 MW. La puissance réactive associée est Q = S × sin φ = 60 Mvar.', true),
  ('intermediaire-04', 'intermediaire', 4, null, 'Quel principe permet aux chambres de combustion DLN (Dry Low NOx) de réduire les NOx sans injection d’eau ou de vapeur ?', '["Une combustion prémélangée pauvre qui abaisse la température de flamme","Une combustion avec excès d’air minimal pour limiter l’oxygène","Un catalyseur placé dans la chaudière de récupération uniquement","Un préchauffage du gaz à très haute température"]'::jsonb, 'A', 'Les NOx thermiques croissent exponentiellement avec la température de flamme. Le prémélange air-gaz pauvre homogénéise le mélange et évite les zones chaudes stœchiométriques. En contrepartie, la plage de stabilité est étroite (risques de pulsations et de CO à faible charge).', false),
  ('intermediaire-05', 'intermediaire', 5, null, 'Sur une turbine à gaz, un écart de température d’échappement (exhaust spread) qui augmente révèle le plus souvent :', '["Une baisse de la température ambiante","Une combustion non uniforme (injecteur ou brûleur encrassé ou défaillant) ou un thermocouple défaillant","Un excès de pression dans la chaudière de récupération","Un défaut de l’alternateur"]'::jsonb, 'B', 'Les thermocouples d’échappement sont répartis sur la circonférence : un écart important entre eux traduit une répartition inégale de la combustion entre les chambres, ou une mesure défaillante. Il faut distinguer les deux avant de décider d’une inspection des injecteurs.', false),
  ('intermediaire-06', 'intermediaire', 6, null, 'Qu’est-ce que la corrosion assistée par l’écoulement (FAC) dans un circuit eau-vapeur ?', '["Une fissuration due aux chlorures sous contrainte","Un dépôt de silice sur les ailettes de la turbine à vapeur","Une corrosion provoquée par un contact galvanique entre deux métaux","La dissolution de la couche protectrice de magnétite sous l’effet de l’écoulement, favorisée par un pH bas et un milieu réducteur"]'::jsonb, 'D', 'La FAC amincit progressivement les tubes en acier au carbone (économiseurs, évaporateurs basse pression, coudes). Elle se maîtrise par un pH d’eau d’alimentation adapté, un traitement oxygéné ou un choix de matériaux plus résistants.', false),
  ('intermediaire-07', 'intermediaire', 7, null, 'Pourquoi réalise-t-on un cycle de purge avant l’allumage d’une turbine à gaz ?', '["Pour préchauffer le rotor","Pour refroidir l’huile de graissage","Pour étalonner les thermocouples","Pour évacuer tout mélange combustible résiduel du circuit des gaz et éviter une explosion à l’allumage"]'::jsonb, 'D', 'La turbine est lancée par le dispositif de démarrage pour balayer plusieurs volumes de la ligne d’échappement et de la chaudière de récupération. Cela évacue le gaz non brûlé éventuel avant que l’allumage ne soit autorisé.', false),
  ('intermediaire-08', 'intermediaire', 8, null, 'Que permet (et ne permet pas) un lavage du compresseur d’une turbine à gaz ?', '["Il récupère la dégradation due à l’encrassement, mais pas celle due à l’érosion ou à l’usure des aubes","Il récupère toute la dégradation de performance","Il ne récupère que la dégradation de la turbine, pas celle du compresseur","Il ne sert qu’à refroidir le compresseur"]'::jsonb, 'A', 'Le lavage (en ligne ou hors ligne) élimine les dépôts sur les aubes et rétablit le débit et le rendement du compresseur. La dégradation non récupérable (érosion, jeux, corrosion) ne se corrige qu’en révision.', false),
  ('intermediaire-09', 'intermediaire', 9, null, 'Pourquoi utilise-t-on une régulation de niveau à trois éléments sur le ballon d’une chaudière de récupération ?', '["Pour mesurer la conductivité de l’eau","Pour compenser les phénomènes de gonflement et de retrait (swell/shrink) en combinant niveau, débit de vapeur et débit d’eau d’alimentation","Pour réguler la température de la vapeur surchauffée","Pour équilibrer la pression entre trois ballons"]'::jsonb, 'B', 'Lors d’un appel de vapeur, la pression chute et les bulles de vapeur gonflent le mélange : le niveau mesuré monte alors que la masse d’eau diminue. La mesure du débit de vapeur permet d’anticiper et d’éviter une mauvaise réaction du régulateur, source de déclenchement sur niveau haut ou bas.', false),
  ('intermediaire-10', 'intermediaire', 10, null, 'Quel phénomène la protection contre la perte d’excitation (ANSI 40) d’un alternateur cherche-t-elle à détecter et à limiter ?', '["Une surtension du réseau","L’alternateur absorbe de la puissance réactive du réseau et peut passer en fonctionnement asynchrone, avec échauffement du rotor et du stator","Un défaut d’isolement du bobinage statorique uniquement","Une survitesse de la turbine"]'::jsonb, 'B', 'Sans excitation, l’alternateur perd le synchronisme et fonctionne en générateur asynchrone en absorbant de la puissance réactive du réseau. Cela provoque des courants induits dans le rotor et un surcourant statorique, donc des échauffements. La protection (code ANSI 40) détecte généralement une impédance vue des bornes qui entre dans une caractéristique mho côté capacitif.', false),
  ('expert-01', 'expert', 1, null, 'Un ventilateur piloté par variateur passe de 100 % à 80 % de sa vitesse. Quelle est approximativement la puissance absorbée (par rapport à la puissance nominale) ?', '["80 %","64 %","51 %","40 %"]'::jsonb, 'C', 'Selon les lois de similitude des ventilateurs, la puissance varie comme le cube de la vitesse : 0,8³ = 0,512, soit environ 51 % de la puissance nominale. Le débit, lui, baisse proportionnellement à la vitesse (80 %).', true),
  ('expert-02', 'expert', 2, null, 'Pourquoi réchauffe-t-on le gaz naturel avant (ou pendant) sa détente dans un poste de détente ?', '["Pour compenser le refroidissement dû à la détente (Joule-Thomson) et éviter hydrates et givre","Pour augmenter la pression en aval","Pour augmenter l’indice de Wobbe","Pour faire monter le PCS du gaz"]'::jsonb, 'A', 'La détente du gaz (effet Joule-Thomson) abaisse sa température d’environ 0,4 à 0,5 °C par bar. Sans réchauffage, la température peut passer sous 0 °C et former des hydrates ou du givre, et abaisser la température du gaz en dessous des valeurs admises par la turbine.', false),
  ('expert-03', 'expert', 3, null, 'Pourquoi limite-t-on le taux d’humidité de la vapeur dans les derniers étages d’une turbine à vapeur ?', '["Pour augmenter la production de vapeur","Pour limiter l’érosion des aubes des derniers étages par les gouttelettes d’eau","Pour réduire la consommation d’eau","Pour augmenter la pression au condenseur"]'::jsonb, 'B', 'Des gouttelettes d’eau accélérées frappent les aubes des derniers étages et les érodent. C’est pourquoi on limite le taux d’humidité en fin de détente (titre généralement supérieur à environ 0,88–0,9), ce qui borne la pression minimale au condenseur pour un cycle donné.', false),
  ('expert-04', 'expert', 4, null, 'Une turbine à gaz a un rendement de 38 %. Sa chaudière de récupération récupère 85 % de la chaleur des gaz d’échappement et le cycle vapeur a un rendement de 35 %. En négligeant les autres pertes, quel est le rendement du cycle combiné ?', '["Environ 48 %","Environ 52 %","Environ 56 %","Environ 60 %"]'::jsonb, 'C', 'En négligeant les pertes mécaniques et électriques : η_cc = η_TG + (1 − η_TG) × η_chaudière × η_vapeur = 0,38 + 0,62 × 0,85 × 0,35 ≈ 0,38 + 0,184 = 0,564, soit environ 56 %.', true),
  ('expert-05', 'expert', 5, null, 'Pourquoi le rendement marginal de la post-combustion (duct burner) d’une chaudière de récupération est-il inférieur au rendement global du cycle combiné ?', '["Parce qu’elle augmente les pertes par rayonnement","Parce qu’elle élève la température d’entrée de la turbine à gaz","Parce qu’elle produit plus de NOx uniquement","Parce que la chaleur ajoutée n’est valorisée que par le cycle vapeur, dont le rendement est inférieur à celui du cycle combiné"]'::jsonb, 'D', 'La chaleur apportée par la post-combustion n’est convertie que par le cycle vapeur (rendement d’environ 35 à 40 %), alors que le gaz brûlé dans la turbine bénéficie des deux cycles. La post-combustion apporte de la puissance de pointe et de la souplesse, au prix d’un rendement marginal plus faible.', false),
  ('expert-06', 'expert', 6, null, 'Dans le suivi de la performance énergétique (ISO 50001), que représente la courbe CUSUM ?', '["La somme cumulée des écarts entre consommation réelle et consommation prévue par le modèle de référence, dont la pente révèle les dérives et les économies","La moyenne des consommations sur douze mois","Le maximum de consommation observé en un mois","Le ratio entre l’énergie consommée et le prix du combustible"]'::jsonb, 'A', 'Le CUSUM trace la somme cumulée des écarts entre consommation réelle et consommation attendue (modèle de référence, par exemple une régression sur la charge et la température). Une pente descendante révèle des économies, une pente montante une dérive. Il rend visibles des dérives faibles que la lecture mensuelle masque.', false),
  ('expert-07', 'expert', 7, null, 'Les émissions de NOx d’une turbine à gaz sont mesurées à 25 ppm avec 14 % d’O₂ (sec). Quelle est la concentration corrigée à la référence de 15 % d’O₂ ?', '["18,5 ppm","21,4 ppm","25,0 ppm","29,2 ppm"]'::jsonb, 'B', 'C_corrigé = C_mesuré × (20,9 − 15) / (20,9 − O₂ mesuré) = 25 × 5,9 / 6,9 ≈ 21,4 ppm. Quand l’O₂ mesuré est inférieur à 15 %, les fumées sont moins diluées que la référence : la concentration corrigée est donc plus basse.', true),
  ('expert-08', 'expert', 8, null, 'Pourquoi une chaudière de récupération moderne comporte-t-elle plusieurs niveaux de pression (HP/MP/BP) plutôt qu’un seul ?', '["Pour augmenter la pression de la vapeur à l’échappement","Pour réduire le nombre d’équipements","Pour mieux épouser la courbe de refroidissement des gaz, réduire les irréversibilités et abaisser la température des fumées en cheminée","Pour supprimer le besoin de dégazeur"]'::jsonb, 'C', 'Les gaz se refroidissent de manière quasi continue de 600 °C à moins de 100 °C, alors que l’eau change d’état à température constante. Plusieurs niveaux de pression permettent de mieux ajuster les deux courbes, donc de réduire les écarts de température (irréversibilités) et de descendre la température en cheminée, au prix d’un coût d’investissement plus élevé.', false),
  ('expert-09', 'expert', 9, null, 'Pourquoi la protection terre stator à 100 % d’un alternateur utilise-t-elle l’harmonique 3 ?', '["Pour détecter les défauts entre phases","Pour mesurer la fréquence du réseau","Pour couvrir la zone proche du neutre, où la tension fondamentale d’un défaut à la terre est trop faible pour être détectée","Pour déclencher plus vite en cas de survitesse"]'::jsonb, 'C', 'La protection terre stator à minimum de tension homopolaire (59N) couvre environ 90 à 95 % de l’enroulement. Près du neutre, la tension fondamentale d’un défaut est trop faible. La mesure de l’harmonique 3 (ou l’injection de signal) permet d’atteindre les derniers pourcents du bobinage : c’est la protection terre stator à 100 %.', false),
  ('expert-10', 'expert', 10, null, 'Une centrale de 400 MW produit 2 400 GWh sur une année de 8 760 heures. Quel est son facteur de charge ?', '["Environ 48 %","Environ 58 %","Environ 68 %","Environ 78 %"]'::jsonb, 'C', 'Facteur de charge = énergie produite ÷ (puissance nominale × heures) = 2 400 ÷ (0,4 × 8 760) = 2 400 ÷ 3 504 ≈ 0,685, soit environ 68 %.', true)
